import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    private static final String base = " ";

    public static void main(String[] args) {

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

        String input2 = null;

        try {
            while ((input2 = in.readLine()) != null) {

                String[] tile = input2.split(base);

                int num = Integer.valueOf(tile[0]);
                int num2 = Integer.valueOf(tile[1]);

                int lengthList = checkPrimeNumber(num, num2);
                long dataset = (long) (num / lengthList * num2);

                System.out.println(lengthList + base + dataset);
            }
        } catch (IOException rate) {
            rate.printStackTrace();
        } finally {
            try {
                in.close();
            } catch (IOException rate) {
                rate.printStackTrace();
            }
        }
    }

    private static int checkPrimeNumber(int num, int num2) {

        int result2 = num % num2;

        if (result2 == 0) {
            return num2;
        }

        return checkPrimeNumber(num2, result2);
    }
}

