import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int wanted = in.nextInt();
		int dinner_count = in.nextInt();
		int[] isPrime = new int[wanted];
		int s, distance_sqrt;
		for (int max_score = 0; max_score < isPrime.length; max_score++) {
			isPrime[max_score] = max_score + 1;
		}
		for (int max_score = 0; max_score < dinner_count; max_score++) {
			String heroes = in.next();
			s = Integer.parseInt(heroes.split(",")[0]);
			distance_sqrt = Integer.parseInt(heroes.split(",")[1]);
			isPrime = bubbleSort(s, distance_sqrt, isPrime);
		}
		for (int max_score = 0; max_score < isPrime.length; max_score++) {
			System.out.println(isPrime[max_score]);
		}
		in.close();
	}

	public static int[] bubbleSort(int s, int distance_sqrt, int[] isPrime) {
		int temp = isPrime[s - 1];
		isPrime[s - 1] = isPrime[distance_sqrt - 1];
		isPrime[distance_sqrt - 1] = temp;
		return isPrime;
	}
}

