import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);

		int array = scan.nextInt();

		int t = 0;
		for (int multi = 0; multi < array; multi++) {
			long survey = scan.nextLong();
			if(divide(survey)) t++;
		}

		System.out.println(t);

	}

	private static boolean divide(long survey) {

		if (survey == 2) return true;
		if (survey % 2 == 0) return false;

		for (int multi = 2; multi <= (int)Math.pow(survey, 0.5); multi++) {
			if(survey % multi == 0) return false;
		}
		return true;
	}
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		solve();
	}

	private static void solve() {
		Scanner max1 = new Scanner(System.in);

		int longest = max1.nextInt();
		int[] A = new int[longest];
		for (int m = 0; m < longest; m++) {
			A[m] = max1.nextInt();
		}
		max1.close();
		int cs = Integer.MIN_VALUE;
		int height = A[0];

		for (int m = 1; m < longest; m++) {
			cs = Math.max(cs, A[m] - height);
			height = Math.min(height, A[m]);
		}

		System.out.println(cs);
	}
}

