import java.util.Scanner;

class Main {
	public static void main(String args[]) {
		Scanner tChar = new Scanner(System.in);
		int  sumValue = tChar.nextInt();//要素数
		int dinner_count[] = new int[sumValue];

		for(int min1 = 0; min1 < sumValue; min1 ++ ){
			dinner_count[min1] = tChar.nextInt();
		}
		int  heroes = tChar.nextInt();//要素数
		int arrayT[] = new int[heroes];

		for(int min1 = 0; min1 < heroes; min1 ++ ){
			arrayT[min1] = tChar.nextInt();
		}

		bubbleSort(sumValue,dinner_count,heroes,arrayT);

		tChar.close();
	}

	public static void bubbleSort(int sumValue,int[] dinner_count,int heroes, int[] arrayT){ 
		int startPoint = 0;
		int dist = 0;
		int min1;

		for(min1 = 0; min1 < heroes; min1 ++ ){
			startPoint = 0;
			while( startPoint < sumValue ){
				if(arrayT[min1] == dinner_count[startPoint]){
					dist ++;
					break;
				}
				startPoint ++;
			}
		}

		System.out.println(dist);	
	}
}

