	public static void sort (int n, int[] scannerArrayB) {

		int total = 0;
		double stdIn = 0;
		for (int mid = 0; mid < n; mid++) {
			// １人目は必ず０
			if (mid == 0) {
				total = scannerArrayB[mid];
				continue;
			}

			// ステップ足し込む
			if (total > scannerArrayB[mid]) {
				stdIn = stdIn + (total - scannerArrayB[mid]);
			}

			// 必要であれば最大を入れ替える
			if (scannerArrayB[mid] > total) {
				total = scannerArrayB[mid];
			}

