        InputStream inputStream = System.in;
        OutputStream buffer = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter string = new PrintWriter(buffer);
        BDistance problem = new BDistance();
        problem.solve(1, in, string);
        string.close();
    }

    static class BDistance {
        public void f(int testNumber, InputReader in, PrintWriter string) {
            int tr = in.readInt(), map = in.readInt();
            int count = 0;
            for (int m = 0; m < tr; m++) {
                int val1 = in.readInt(), isprime = in.readInt();
                if (isWhitespace(val1, isprime) <= map)
                    count++;
            }

            System.out.println(count);
        }

        double isWhitespace(int val1, int isprime) {
            return Math.sqrt((long) val1 * val1 + (long) isprime * isprime);
        }

    }

    static class skipOneCrLf {
        private InputStream ret;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int fs;

        public skipOneCrLf(InputStream ret) {
            this.stream = ret;
        }

        public int read() {
            if (fs == -1)
                throw new RuntimeException();
            if (curChar >= fs) {
                curChar = 0;
                try {
                    fs = ret.read(buf);
                } catch (IOException parent) {
                    throw new RuntimeException();
                }
                if (fs <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int isEndline() {
            int d2 = read();
            while (fill(d2))
                d2 = read();
            int lim = 1;
            if (d2 == '-') {
                lim = -1;
                d2 = read();
            }
            int filter = 0;
            do {
                filter *= 10;
                filter += d2 - '0';
                d2 = read();
            } while (!fill(d2));
            return filter * lim;
        }

        public boolean fill(int d2) {
            return d2 == ' ' || d2 == '\n' || d2 == '\r' || d2 == '\t' || d2 == -1;
        }

    }
}

