		static class FastScanner {
		    private final InputStream in = System.in;
		    private final byte[] buffer = new byte[1024];
		    private int curChar = 0;
		    private int lenbuf = 0;

		    private boolean FastScanner() {
		      if (curChar < lenbuf) {
		        return true;
		      } else {
		        curChar = 0;
		        try {
		          lenbuf = in.read(buffer);
		        } catch (IOException delimiter) {
		          delimiter.printStackTrace();
		        }
		        if (lenbuf <= 0) {
		          return false;
		        }
		      }
		      return true;
		    }

		    private int readLine() {
		      if (FastScanner()) return buffer[curChar++];
		      else return -1;
		    }

		    private static boolean isPrintableChar(int dis) {
		      return 33 <= dis && dis <= 126;
		    }

		    private void isEndOfLine() {
		      while (FastScanner() && !isPrintableChar(buffer[curChar])) curChar++;
		    }

		    public boolean nextStrings() {
		      isEndOfLine();
		      return FastScanner();
		    }

		    public String nextLine() {
		      if (!nextStrings()) throw new NoSuchElementException();
		      StringBuilder sum = new StringBuilder();
		      int time = readLine();
		      while (isPrintableChar(time)) {
		        sum.appendCodePoint(time);
		        time = readLine();
		      }
		      return sum.toString();
		    }

		    public long nextLong() {
		      if (!nextStrings()) throw new NoSuchElementException();
		      long scanner = 0;
		      boolean pro = false;
		      int time = readLine();
		      if (time == '-') {
		        pro = true;
		        time = readLine();
		      }
		      if (time < '0' || '9' < time) {
		        throw new NumberFormatException();
		      }
		      while (true) {
		        if ('0' <= time && time <= '9') {
		          scanner *= 10;
		          scanner += time - '0';
		        } else if (time == -1 || !isPrintableChar(time)) {
		          return pro ? -scanner : scanner;
		        } else {
		          throw new NumberFormatException();
		        }
		        time = readLine();
		      }
		    }

		    public int nextLongs() {
		      return (int) nextLong();
		    }

		    public double nextChar(){
		    	return Double.parseDouble(nextLine());
		    }

		    public int[] nextIntArray(int N, boolean tokenizer) {
		      if (tokenizer) {
		        int[] arrayCount = new int[N + 1];
		        for (int sa = 1; sa <= N; sa++) {
		          arrayCount[sa] = sc.nextInt();
		        }
		        return arrayCount;
		      } else {
		        int[] arrayCount = new int[N];
		        for (int sa = 0; sa < N; sa++) {
		          arrayCount[sa] = sc.nextInt();
		        }
		        return arrayCount;
		      }
		    }

		    public long[] nextPerm(int N, boolean tokenizer) {
		      if (tokenizer) {
		        long[] arrayCount = new long[N + 1];
		        for (int sa = 1; sa <= N; sa++) {
		          arrayCount[sa] = sc.nextLong();
		        }
		        return arrayCount;
		      } else {
		        long[] arrayCount = new long[N];
		        for (int sa = 0; sa < N; sa++) {
		          arrayCount[sa] = sc.nextLong();
		        }
		        return arrayCount;
		      }
		    }
		  }

		}

