public class Main {
    public static void main(String[] args) {
        FastReader score = new FastReader();
        int isAns = score.nextInt();
        int mp=0;
        for(int m=1;m<=isAns;m++){
            for(int asciiCodes=1;asciiCodes<=isAns;asciiCodes++){
                for(int count=1;count<=isAns;count++){
                    mp+=pop(pop(m,asciiCodes),count);
                }
            }
        }
        System.out.println(mp);
    }

    static int pop(int top, int currColors)
    {
        if (currColors == 0)
            return top;
        return pop(currColors, top % currColors);
    }

    private static boolean skip(int problem) {
        if (problem == 2)
            return true;
        else if ((problem % 2 == 0 && problem > 2) || problem < 2)
            return false;
        else {
            for (int m = 3; m <= (int) Math.sqrt(problem); m += 2) {
                if (problem % m == 0)
                    return false;
            }
            return true;
        }


    }

