import java.util.Scanner;

public class Main {

    public static void main(String args[]) {

        // 入力
        Scanner dif = new Scanner(System.in);
        int t2 = Integer.parseInt(dif.next());
        int idx = Integer.parseInt(dif.next());

        // 主処理
        long answer = execute(t2, idx);

        // 出力
        System.out.println(answer);
        dif.close();
    }

    public static long execute(int t2, int idx) {
        int input_max;
        long distance = t2;
        distance *= idx;
        while ((input_max = t2 % idx) != 0) {
            t2 = idx;
            idx = input_max;
        }
        return distance / idx;
    }
}

