import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);

		long w1 = in.nextLong();
		long sqrtNum = in.nextLong();
		long A = in.nextLong();
		long small = in.nextLong();

		System.out.println(readByte(sqrtNum, A, small) - readByte(w1 - 1, A, small));

		in.close();
	}

	// 1以上limit以下の範囲でｃ、ｄの倍数でないものの個数を返す
	private static long readByte(long startPoint, long A, long small) {

		// cの倍数の個数
		long temp = startPoint / A;

		// dの倍数の個数
		long len = startPoint / small;

		// c, dの最大公約数
		long flg = getGCD(A, small);

		// c,dの最小公倍数
		long shiharai = A * small / flg;

		// lcm の個数
		long m_lcm = startPoint / shiharai;

		return startPoint - temp - len + m_lcm;
	}

	// 最大公約数を求める
	private static long getGCD(long A, long small) {
		if ( A % small == 0 ) return small;
		else return getGCD(small, A % small);
	}
}

