class FastScanner {
    private final InputStream in = System.in;
    private final byte[] bufPointer = new byte[1024];
    private int ptr = 0;
    private int bufsiz = 0;
    private boolean nextPermutation() {
        if (ptr < bufsiz) {
            return true;
        } else {
            ptr = 0;
            try {
                bufsiz = in.read(bufPointer);
            } catch (IOException par) {
                par.printStackTrace();
            }
            if (bufsiz <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readBody() {
        if (nextPermutation())
            return bufPointer[ptr++];
        else
            return -1;
    }

    private boolean printLine(int ans) {
        return 33 <= ans && ans <= 126;
    }

    public boolean nextStrings() {
        while (nextPermutation() && !printLine(bufPointer[ptr]))
            ptr++;
        return nextPermutation();
    }

    public String next() {
        if (!nextStrings())
            throw new NoSuchElementException();
        StringBuilder sub = new StringBuilder();
        int data = readBody();
        while (printLine(data)) {
            sub.appendCodePoint(data);
            data = readBody();
        }
        return sub.toString();
    }

    public long nextInts() {
        if (!nextStrings())
            throw new NoSuchElementException();
        long n1 = 0;
        boolean minValue = false;
        int data = readBody();
        if (data == '-') {
            minValue = true;
            data = readBody();
        }
        if (data < '0' || '9' < data) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= data && data <= '9') {
                n1 *= 10;
                n1 += data - '0';
            } else if (data == -1 || !printLine(data)) {
                return minValue ? -n1 : n1;
            } else {
                throw new NumberFormatException();
            }
            data = readBody();
        }
    }

    public int nextInt() {
        long n2 = nextInts();
        if (n2 < Integer.MIN_VALUE || n2 > Integer.MAX_VALUE)
            throw new NumberFormatException();
        return (int) n2;
    }

    public double nextByte() {
        return Double.parseDouble(next());
    }
}

