public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter tokenizer = new PrintWriter(outputStream);
        CPrison solver = new CPrison();
        solver.solve(1, in, tokenizer);
        tokenizer.close();
    }

    static class CPrison {
        public void solveSub(int testNumber, FastReader sum, PrintWriter check) {
            int nl = sum.nextInt(), dis = sum.nextInt(), a[] = new int[nl + 1], max = 0;
            for (int ii = 0; ii < dis; ii++) {
                a[sum.nextInt() - 1]++;
                a[sum.nextInt()]--;
            }
            if (a[0] == dis) max++;
            for (int ii = 1; ii < nl; ii++) {
                a[ii] = a[ii - 1] + a[ii];
                if (a[ii] == dis) max++;
            }
            check.println(max);
        }

    }

    static class Reader {
        private InputStream stream;
        private byte[] bufsiz = new byte[1024];
        private int writer;
        private int snumChars;
        private FastReader.SpaceCharFilter filter;

        public Reader(InputStream stream) {
            this.stream = stream;
        }

        public int readInt() {

            if (snumChars == -1)
                throw new InputMismatchException();

            if (writer >= snumChars) {

                writer = 0;

                try {
                    snumChars = stream.read(bufsiz);
                } catch (IOException te) {
                    throw new InputMismatchException();
                }

                if (snumChars <= 0)
                    return -1;
            }

            return bufsiz[writer++];
        }

        public int nextLong() {

            int cc = readInt();

            while (LightWriter(cc))
                cc = readInt();

            int sign = 1;

            if (cc == '-') {
                sign = -1;
                cc = readInt();
            }

            int par = 0;

            do {
                if (cc < '0' || cc > '9')
                    throw new InputMismatchException();

                par *= 10;
                par += cc - '0';
                cc = readInt();
            }
            while (!LightWriter(cc));

            return par * sign;
        }

        public boolean LightWriter(int cc) {

            if (filter != null)
                return filter.isSpaceChar(cc);

            return cc == ' ' || cc == '\n' || cc == '\r' || cc == '\t' || cc == -1;
        }

        public interface SpaceCharFilter {
            public boolean LightWriter(int ch);

        }

    }
}

