/*
 * 0を区切りに1以上が続く区間をスタックで管理しようとしたが、よく分からなくなり断念。
 * 方針を以下に変更
 * ①0が出てくるまで、目標の高さを先頭からマイナス1する
 * ②0が出てきた場合、先頭に戻る。
 *   ただし、1以上の区間に遭遇していない(先頭から連続する0の区間の場合) 例:[0,0,0,0,2,2,3]とか
 *   場合は先頭に戻らない
 * ③終了条件を満たすまで①、②を繰り返す。
 *   ⇒目標の高さが全て0になったら終了
 */

import java.util.Scanner;
class Main{
  public static void main(String[] args) {
    Main orderedList = new Main();
    orderedList.run();
  }
  private void unite() {

    Scanner s11 = new Scanner(System.in);
    int reader = s11.nextInt();
    int[] max_second = new int[reader];
    int max_first_position = 0;
    for(int shukudaiyaruhi=0; shukudaiyaruhi<reader; shukudaiyaruhi++) {
      max_second[shukudaiyaruhi] = s11.nextInt();
    }

    boolean red = true;
    while(red){
      //out(ary);

      // 終了条件
      red = false;
      for(int shukudaiyaruhi=0; shukudaiyaruhi<reader; shukudaiyaruhi++) {
        if(max_second[shukudaiyaruhi] > 0 ) {
          red = true;
          break;
        }
      }
      boolean end = true;
      for(int shukudaiyaruhi=0; shukudaiyaruhi<reader; shukudaiyaruhi++) {

        // 先頭の0を読み飛ばす
        if(max_second[shukudaiyaruhi] <= 0 && end) {
          continue;
        }

        // 1以上の区間をマイナス1する。1以上の区間が終わったらブレイク。
        if(max_second[shukudaiyaruhi] <= 0) break;
        max_second[shukudaiyaruhi]--;
        end = false;
      }
      // カウントアップ
      if (!end) max_first_position++;

    }
    System.out.println(max_first_position);
  }
