	public static int solve(int[]sz, int mx) {
		int[]inputs=new int[sz.length];
		Arrays.fill(inputs, Integer.MAX_VALUE);
		inputs[0]=0;
		for(int suanchang=1;suanchang<sz.length;suanchang++) {
			for(int kotae=1;kotae<=mx;kotae++) {
				inputs[suanchang]=Math.min(inputs[suanchang], suanchang-kotae>=0?(inputs[suanchang-kotae]+Math.abs(sz[suanchang]-sz[suanchang-kotae])):Integer.MAX_VALUE);
			}
		}
		return inputs[inputs.length-1];
	}


}

