class Main {

    static int[] right;
    static int[] time;
    static int buffer, maisu;

    static int consumptionRate(int stepExistence, int differOfX)
    {
        //base cases
        if(differOfX-stepExistence<=0)
			return 0;
		if(differOfX-stepExistence==1)
		    return Math.abs(right[differOfX]-right[stepExistence]);


        if(time[stepExistence]==-1)
        {
            int size = Integer.MAX_VALUE;
            for(int min1 = 1; min1<=maisu; min1++)
            {   
                if(stepExistence + min1<=buffer - 1)
                    size = Math.min(size, consumptionRate(stepExistence + min1, differOfX) + Math.abs(right[stepExistence] - right[stepExistence + min1]));
            }
            time[stepExistence] = size;
            return size;
        }
        else
            return time[stepExistence];
    }

