		int k = lcm.nextInt();
		int count = lcm.nextInt();
		int currentDiff = lcm.nextInt();
		int c = lcm.nextInt();
		int first = lcm.nextInt();
		int t2 = 0;
		boolean lastX = k + count > currentDiff * 2;
		boolean target = k > currentDiff * 2;
		boolean isCheaperThanB = count > currentDiff * 2;

		if (lastX) {
			int num = Math.min(c, first);
			t2 += num * 2 * currentDiff;
			c -= num;
			first -= num;
		}
		if (target) {
			t2 += c * currentDiff * 2;
			c = 0;
		}
		if (isCheaperThanB) {
			t2 += first * currentDiff * 2;
			first = 0;
		}
		t2 += c * k;
		t2 += first * count;

		lcm.close();
		System.out.print(t2);
	}
}

