public class Main {
	public static void main(String[] args) {
		FastReader scan = new FastReader();
		int scn = scan.nextInt();
		int d = scan.nextInt();
		int testNumber = 0;

		for (int min = scn; min <= d; min++) {
			if (isPrime(min)) {
				testNumber++;
			}
		}
		System.out.println(testNumber);
	}

	private static boolean isPrime(int reader) {
		int val = reader;
		int tokens = 0;
		while (val != 0) {
			tokens *= 10;
			tokens += (val % 10);
			val /= 10;
		}
		return reader == tokens;
	}

    static class FastScanner {
	    BufferedReader reg;
	    StringTokenizer se;

	    public FastScanner() {
	      reg = new BufferedReader(new InputStreamReader(System.in));
	    }

	    String nextIntArr() { 
	      while (se == null || !se.hasMoreElements()) {
	        try {
	          se = new StringTokenizer(reg.readLine());
	        } catch (IOException  re) {
	          re.printStackTrace();
	        }
	      }
	      return se.nextToken();
	    }

	    int nextLongArr() {
	      return Integer.parseInt(nextIntArr());
	    }

	    long nextLong() {
	      return Long.parseLong(nextIntArr());
	    }

	    double nextLongArray() { 
