public class Main {
  private static int gcd(int n) {
    int unit = 0;
    while (n > 1) {
      n /= 2;
      unit++;
    }
    return 1 << unit;
  }

  private static void debug(ContestReader matcher, PrintWriter out) {
    int n = matcher.nextInt();
    out.println(gcd(n));
  }

  public static void main(String[] args) {
    ContestReader matcher = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    debug(matcher, out);
    out.flush();
  }
}

