public class Main {

	public static void main(String[] args) {
		Scanner re = new Scanner(System.in);
		int val = re.nextInt();
		int total = re.nextInt();
		String[] data = new String[val];
		Map<String, String> max = new TreeMap<String,String>();
		for(int amida=0;amida<val;amida++) {
			data[amida] = re.next();
			if(max.get(data[amida])==null) {
				max.put(data[amida], data[amida]);
			}
			else {
				max.put(data[amida]+amida, data[amida]);
			}
		}
		total=total+1;
		for(String sum:max.values()) {
			System.out.print(sum);
		}
		System.out.println();
		re.close();
	}

}
